def _reachability_bitsets(G, topo_order):
    """Return the strict reachability relation of a DAG as integer bitsets.

    Node ``topo_order[i]`` is identified with bit ``i``. The returned list holds,
    for each position ``i``, an integer whose set bits are the positions of the
    nodes reachable from ``topo_order[i]`` by a non-empty path.
    """
    index = {v: i for i, v in enumerate(topo_order)}
    succ = G._succ
    reach = [0] * len(topo_order)
    for i in range(len(topo_order) - 1, -1, -1):
        bits = 0
        for w in succ[topo_order[i]]:
            j = index[w]
            bits |= (1 << j) | reach[j]
        reach[i] = bits
    return reach


def _bits_to_indices(bits):
    """Return the positions of the set bits of the nonnegative integer `bits`."""
    indices = []
    while bits:
        low = bits & -bits
        indices.append(low.bit_length() - 1)
        bits ^= low
    return indices


def _maximum_bipartite_matching_size(adj, n):
    """Size of a maximum matching of a bipartite graph via Hopcroft--Karp.

    Both sides of the bipartite graph are ``range(n)`` and ``adj[u]`` lists the
    right-side neighbors of the left node ``u``. The search for augmenting
    paths is iterative so that long paths do not exhaust the recursion limit.
    """
    unmatched = -1
    match_left = [unmatched] * n
    match_right = [unmatched] * n
    infinity = n + 1
    size = 0
    while True:
        # Breadth-first search building the layers of alternating paths.
        dist = [infinity] * n
        queue = deque()
        for u in range(n):
            if match_left[u] == unmatched:
                dist[u] = 0
                queue.append(u)
        found_free = False
        while queue:
            u = queue.popleft()
