                    queue.append(w)
        if not found_free:
            return size
        # Depth-first search for vertex-disjoint augmenting paths.
        nbr_iters = {}
        for root in range(n):
            if match_left[root] != unmatched:
                continue
            stack = [root]
            via = []
            nbr_iters.setdefault(root, iter(adj[root]))
            while stack:
                u = stack[-1]
                for v in nbr_iters[u]:
                    w = match_right[v]
                    if w == unmatched:
                        via.append(v)
                        for left, right in zip(stack, via):
                            match_left[left] = right
                            match_right[right] = left
                        size += 1
                        stack = []
