                    if dist[w] == dist[u] + 1:
                        via.append(v)
                        stack.append(w)
                        nbr_iters.setdefault(w, iter(adj[w]))
                        break
                else:
                    # dead end: no augmenting path continues through u
                    dist[u] = infinity
                    stack.pop()
                    if via:
                        via.pop()


