cd /tmp && PYTHONPATH=/app timeout 600 python - <<'EOF' 2>&1 | tail -20
import networkx as nx, random
from networkx.algorithms.planarity import check_planarity_recursive
bad = 0
for seed in range(3000):
    rng = random.Random(seed)
    n = rng.randint(0, 9)
    m = rng.randint(0, 3 * n)
    G = nx.MultiGraph() if rng.random() < 0.3 else nx.Graph()
    if rng.random() < 0.3:
        G = nx.MultiDiGraph() if G.is_multigraph() else nx.DiGraph()
    G.add_nodes_from(range(n))
    for _ in range(m):
        if n: G.add_edge(rng.randrange(n), rng.randrange(n))
    try:
        ok1, r1 = nx.check_planarity(G, counterexample=True)
        ok2, r2 = check_planarity_recursive(G, counterexample=True)
        assert ok1 == ok2
        if ok1:
            r1.check_structure(); r2.check_structure()
            ge = {(u, v) for u, v in nx.Graph(G).edges() if u != v}
            ge |= {(v, u) for u, v in ge}
            assert set(r1.edges()) == ge and set(r2.edges()) == ge, "edges"
            assert set(r1.nodes()) == set(G.nodes()), "nodes"
        else:
            assert len(r1) in (5, 6), len(r1)
    except Exception as e:
        bad += 1
        if bad < 10:
            print(seed, type(e).__name__, e, list(G.edges()))
print("bad", bad)
EOF

